// Shared contract between the art loader (art.ts), the map (map.ts) and the painted terrain
// (terrainLayer.ts): drawn tree/shrub sprites for forests and hills, and what kind of thing a
// ground footprint belongs to. Types only plus the list of tree ids; no PixiJS objects created here.
import type { Texture } from 'pixi.js';

/**
 * Tree and shrub art in `public/assets/terrain/<id>.svg` (generated by tools/art/, docs/ART.md
 * "Forests"). Same world scale as the buildings; the root `<svg>` carries `data-anchor="x y"`
 * at the trunk foot. No owner-color layer.
 */
export const TREE_ART_IDS = [
  'pine1',
  'pine2',
  'pine3',
  'cypress1',
  'cypress2',
  'oak1',
  'oak2',
  'oak3',
  'shrub1',
  'shrub2',
  'shrub3',
  'olive1',
  'olive2',
] as const;

export type TreeArtId = (typeof TREE_ART_IDS)[number];

/** One loaded tree texture, ready to place: sprite anchor (0..1) at the trunk foot, world px per SVG unit. */
export interface TreeSprite {
  texture: Texture;
  anchorX: number;
  anchorY: number;
  scale: number;
}

/** The loaded terrain art; a missing id means "not loaded" (the terrain then draws its own fallback). */
export interface TerrainArt {
  trees: Readonly<Partial<Record<TreeArtId, TreeSprite>>>;
}

/**
 * What a ground footprint belongs to (terrainLayer.ts `TileFootprint.kind`):
 * - 'building': the usual patch under a building (default when absent)
 * - 'unit': the small spot under a unit's token (only trees, shrubs and rocks make room)
 * - 'mineCut' / 'quarryCut': a mine or quarry on hills/mountains; the terrain cuts a rock face or
 *   stepped terraces into its own slope there (the map art `<id>.slope.svg` shows only the works)
 */
export type FootprintKind = 'building' | 'unit' | 'mineCut' | 'quarryCut';
